import freemarker.template.Template;
import freemarker.template.TemplateException;
import org.apache.commons.lang3.StringUtils;

import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.HashMap;
import java.util.Map;

/**
 * Template service for rendering user profile pages using Freemarker.
 */
public class TemplateService {

    private final Configuration configuration;

    public TemplateService() {
        this.configuration = new Configuration(Configuration.VERSION_2_3_31);
        // Set default encoding and other configurations
        this.configuration.setDefaultEncoding("UTF-8");
        // Disable template caching for dynamic templates
        this.configuration.setCacheStorage(freemarker.cache.NullCacheStorage.INSTANCE);
    }

    /**
     * Renders a user profile page based on the provided username and template content.
     *
     * @param username       The username to be passed to the template
     * @param templateContent The Freemarker template content provided by the user
     * @return The rendered HTML string
     * @throws IllegalArgumentException if username is null or empty, or templateContent is null
     * @throws RuntimeException         if template processing fails
     */
    public String renderUserProfile(String username, String templateContent) {
        // Validate inputs
        if (StringUtils.isBlank(username)) {
            throw new IllegalArgumentException("Username cannot be null or empty");
        }
        if (templateContent == null) {
            throw new IllegalArgumentException("Template content cannot be null");
        }

        try {
            // Create a template from the provided content
            Template template = new Template(
                    "userProfile",
                    new StringReader(templateContent),
                    configuration
            );

            // Prepare data model
            Map<String, Object> dataModel = new HashMap<>();
            dataModel.put("username", username);

            // Render the template
            StringWriter writer = new StringWriter();
            template.process(dataModel, writer);

            return writer.toString();
        } catch (IOException e) {
            throw new RuntimeException("Failed to read template content", e);
        } catch (TemplateException e) {
            throw new RuntimeException("Failed to process template", e);
        }
    }
}

